mapper.select:
        select DISTINCT(cat_id) from goods_user_footprint
		where user_id = #{userId,jdbcType=INTEGER}
		order by footprint_date desc
		limit
		#{limitSize,jdbcType=INTEGER}

select distinct a.common_id from goods_user_footprint a left join ${database.prefix.goods}hou_goods_common gc on a.common_id =gc.common_id where gc.shop_status=3
and user_id = #{param.userId,jdbcType=INTEGER}
and footprint_date = #{param.footprintDate,jdbcType=VARCHAR}
ORDER BY footprint_time desc
